#!/usr/bin/env python3
"""Dump raw objects of report.pdf (classic xref) + trailer, decode streams."""
import re
import zlib

with open("report.pdf", "rb") as f:
    data = f.read()

m = re.search(rb"startxref\s+(\d+)", data)
sx = int(m.group(1))

# Parse classic xref table
obj_offsets = {}
lines = data[sx:].split(b"\n")
trailer_start = None
i = 0
while i < len(lines):
    line = lines[i].strip()
    if line == b"xref":
        i += 1
        continue
    if line == b"trailer":
        trailer_start = i + 1
        break
    parts = line.split()
    if len(parts) == 2 and parts[0].isdigit():
        start, count = int(parts[0]), int(parts[1])
        for k in range(count):
            entry = lines[i + 1 + k].split()
            if len(entry) == 3 and entry[2] == b"n":
                obj_offsets[start + k] = int(entry[0])
        i += 1 + count
    else:
        i += 1

print("Object offsets:", obj_offsets)
print("Trailer:", b" ".join(lines[trailer_start:trailer_start + 8])[:500])


def find_obj_end(off):
    return data.find(b"endobj", off) + 6


for num in sorted(obj_offsets):
    off = obj_offsets[num]
    end = find_obj_end(off)
    body = data[off:end]
    head = body[:600]
    print(f"\n===== object {num} (offset {off}, len {end - off}) =====")
    print(head.decode("latin-1"))
    # If it has a stream, try decoding it
    sm = re.search(rb"stream\r?\n", body)
    if sm:
        sstart = sm.end()
        send = body.find(b"endstream")
        raw = body[sstart:send]
        print(f"  [stream raw {len(raw)} bytes]")
        decoded = None
        if b"FlateDecode" in body:
            try:
                decoded = zlib.decompress(raw)
            except Exception as e:
                print("  zlib decode failed:", e)
        if decoded is not None:
            print("  [decoded stream text]:")
            print(decoded[:1500].decode("latin-1"))
        else:
            print("  [raw stream head]:", raw[:200])

